import os
import threading
import traceback

from kodi_six import xbmcgui

from elementum.addon import ADDON_PATH
from elementum.logger import log
from .dialog import *  # NOQA


class DialogSelect(xbmcgui.WindowXMLDialog):
    def __init__(self, *args, **kwargs):
        xbmcgui.WindowXML.__init__(self)
        self.items = list(kwargs['items'])
        self.title = kwargs['title']
        self.count = 0
        self.retval = -1
        self.initialized = False
        self.finished = False
        self.lock = threading.RLock()

    def onInit(self):
        """Initialize controls and populate the first provider batch.

        The initial population must not reset a panel which is still being
        initialized by Kodi. Subsequent progressive snapshots use reset().
        """
        try:
            with self.lock:
                log.info(
                    "Progressive dialog onInit: items=%d thread=%s"
                    % (len(self.items), threading.current_thread().name)
                )

                self.getControl(32501).setLabel(self.title)
                self.count = 0

                for item in self.items:
                    self._addItem(item)

                self.initialized = True
                self.setFocusId(32503)
                self._log_control_size("onInit")
        except Exception as exc:
            self._log_exception("onInit", exc)

    def updateItems(self, items):
        """Replace visible items with the latest complete snapshot."""
        try:
            with self.lock:
                self.items = list(items)
                log.info(
                    "Progressive dialog update requested: items=%d initialized=%s finished=%s thread=%s"
                    % (
                        len(self.items),
                        self.initialized,
                        self.finished,
                        threading.current_thread().name,
                    )
                )

                # An update can arrive before Kodi invokes onInit(). In that
                # case onInit() will render the newest stored snapshot.
                if not self.initialized or self.finished:
                    return

                listControl = self.getControl(32503)
                selected = listControl.getSelectedPosition()
                listControl.reset()
                self.count = 0

                for item in self.items:
                    self._addItem(item)

                if self.count:
                    listControl.selectItem(
                        min(max(selected, 0), self.count - 1)
                    )

                self._log_control_size("update")
        except Exception as exc:
            self._log_exception("updateItems", exc)

    def _log_control_size(self, source):
        try:
            visible_count = self.getControl(32503).size()
        except Exception:
            visible_count = -1

        log.info(
            "Progressive dialog %s complete: added=%d control_size=%d"
            % (source, self.count, visible_count)
        )

    def _log_exception(self, source, exc):
        log.error(
            "Progressive dialog %s failed: %s" % (source, repr(exc))
        )
        for line in traceback.format_exc().splitlines():
            log.error(line)

    def _addItem(self, item):
        labels = item.split('\n')
        label1 = labels[0]
        try:
            label2 = labels[1]
        except:
            label2 = ''
        try:
            icon = labels[2]
        except:
            icon = None
        try:
            multi = labels[3] == 'multi'
        except:
            multi = False
        self.addItem(label1, label2, icon, multi, item)

    def onClick(self, controlId):
        if controlId == 32500:
            # Close Button
            self.close()
        elif controlId == 32503:
            # Panel
            listControl = self.getControl(32503)
            selected = listControl.getSelectedItem()
            if selected:
                self.retval = int(selected.getProperty('index'))
                self.value = selected.getProperty('value')
            self.close()

    def onAction(self, action):
        if action.getId() in [ACTION_PARENT_DIR, KEY_NAV_BACK, ACTION_PREVIOUS_MENU]:  # NOQA
            self.close()

    def close(self):
        self.finished = True
        log.info(
            "Progressive dialog close: choice=%d items=%d"
            % (self.retval, self.count)
        )
        return super(DialogSelect, self).close()

    def result(self):
        return {
            'done': self.finished,
            'choice': self.retval,
            'value': getattr(self, 'value', ''),
        }

    def addItem(self, label1, label2, icon=None, multi=False, value=None):
        listControl = self.getControl(32503)
        item = xbmcgui.ListItem(label1, label2)
        item.setProperty('index', str(self.count))
        item.setProperty('value', value or '')
        if multi:
            item.setArt({'icon': os.path.join(ADDON_PATH, "resources", "img", "multi-cloud.png")})
        else:
            if icon:
                item.setArt({'icon': icon})
            else:
                item.setArt({'icon': os.path.join(ADDON_PATH, "resources", "img", "cloud.png")})
        listControl.addItem(item)
        self.count += 1
